#pragma once

#include <stddef.h>
#include <stdint.h>

// Boot logo for the T-Dongle-S3 display (display.c), generated by
// scripts/gen-lcd-logo.py into lcd_logo.c.
//
// LCD_LOGO_W x LCD_LOGO_H pixels, row by row, run-length encoded as
// (count, colour) pairs of uint16_t; the colour is RGB565 with its bytes
// already swapped into the order the panel reads over SPI. Runs may span
// rows. lcd_logo_rle_len counts uint16_t values, i.e. twice the runs.
#define LCD_LOGO_W 160
#define LCD_LOGO_H 80

extern const uint16_t lcd_logo_rle[];
extern const size_t lcd_logo_rle_len;
